package app.reverb.track.device.advanced.adb;

/**
 * JNI wrapper for the ADB wireless pairing crypto context.
 *
 * Manages a SPAKE2 key exchange followed by AES-128-GCM encrypt/decrypt
 * for the PeerInfo payload exchange. Each instance holds a native pointer
 * to a BoringSSL SPAKE2_CTX and (after {@link #initCipher}) an EVP_AEAD_CTX.
 *
 * Lifecycle:
 * 1. Construct with the pairing password → generates SPAKE2 message
 * 2. Call {@link #getMsg()} to get our SPAKE2 public message
 * 3. Call {@link #initCipher(byte[])} with their SPAKE2 message → derives AES key
 * 4. Use {@link #encrypt(byte[])} / {@link #decrypt(byte[])} for PeerInfo exchange
 * 5. Call {@link #destroy()} when done
 *
 * Thread-safety: NOT thread-safe. Callers must synchronize externally.
 */
public final class PairingContext implements AutoCloseable {

    static {
        System.loadLibrary("reverb_pairing");
    }

    private long nativePtr;

    /**
     * Creates a pairing context as the client (Alice) role.
     *
     * @param password the pairing password (pair code + TLS keying material)
     * @throws IllegalStateException if native SPAKE2 context creation fails
     */
    public PairingContext(byte[] password) {
        nativePtr = nativeConstructor(password);
        if (nativePtr == 0) {
            throw new IllegalStateException("Failed to create native SPAKE2 context");
        }
    }

    /** Returns our SPAKE2 public message to send to the server. */
    public byte[] getMsg() {
        checkNotDestroyed();
        return nativeMsg(nativePtr);
    }

    /**
     * Processes their SPAKE2 message and derives the AES-128-GCM cipher.
     *
     * @param theirMsg the server's SPAKE2 public message
     * @return true if cipher initialization succeeded
     */
    public boolean initCipher(byte[] theirMsg) {
        checkNotDestroyed();
        return nativeInitCipher(nativePtr, theirMsg);
    }

    /**
     * Encrypts plaintext using the derived AES-128-GCM key.
     * Increments the internal encryption sequence counter.
     *
     * @return ciphertext, or null on failure
     */
    public byte[] encrypt(byte[] plaintext) {
        checkNotDestroyed();
        return nativeEncrypt(nativePtr, plaintext);
    }

    /**
     * Decrypts ciphertext using the derived AES-128-GCM key.
     * Increments the internal decryption sequence counter.
     *
     * @return plaintext, or null on failure
     */
    public byte[] decrypt(byte[] ciphertext) {
        checkNotDestroyed();
        return nativeDecrypt(nativePtr, ciphertext);
    }

    /** Releases native resources. Safe to call multiple times. */
    public void destroy() {
        if (nativePtr != 0) {
            nativeDestroy(nativePtr);
            nativePtr = 0;
        }
    }

    @Override
    public void close() {
        destroy();
    }

    private void checkNotDestroyed() {
        if (nativePtr == 0) {
            throw new IllegalStateException("PairingContext has been destroyed");
        }
    }

    // --- Native methods (registered via JNI_OnLoad in adb_pairing_jni.cpp) ---

    private static native long nativeConstructor(byte[] password);
    private static native byte[] nativeMsg(long ptr);
    private static native boolean nativeInitCipher(long ptr, byte[] theirMsg);
    private static native byte[] nativeEncrypt(long ptr, byte[] plaintext);
    private static native byte[] nativeDecrypt(long ptr, byte[] ciphertext);
    private static native void nativeDestroy(long ptr);
}
