    SHIZUKU_PERMISSION_NEEDED, SHIZUKU_PERMISSION_DENIED, SHIZUKU_SERVICE_FAILED,
    COMMAND_FAILED, NOT_EFFECTIVE, BUSY, INVALID_APP,
