package ly.com.tahaben.privileged_access_domain

import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.withContext
import java.util.concurrent.ConcurrentHashMap

/**
 * The layer the UI calls. Rules it keeps:
 *  - It runs a command only inside [grant] or [revoke], which the user starts. [refresh] reads the phone and stored
 *    state and opens no connection.
 *  - Every command is one of [PrivilegedCommand]; nothing here takes free text.
 *  - The link outlives a grant: a second access runs over the same retained key (or Shizuku permission), with no
 *    pairing flow. A pairing code is used once and never kept.
 */
interface PrivilegedAccess {
    /** Link and per-access state. Starts as [PrivilegedStatus.UNCHECKED] until the first [refresh]. */
    val status: StateFlow<PrivilegedStatus>
    val routePreference: StateFlow<RoutePreference>

    /** Re-reads everything. Call when the app returns to the foreground. */
    suspend fun refresh(): PrivilegedStatus

    suspend fun grant(access: Access, route: Route? = null): AccessResult
    suspend fun revoke(access: Access, route: Route? = null): AccessResult

    suspend fun pairSelfAdb(code: PairingCode, pairingPort: Int?): PairingResult
    suspend fun requestShizukuPermission(): ShizukuPermissionResult

    suspend fun setRoutePreference(preference: RoutePreference)

    /** The user asked to forget the retained adb key. */
    suspend fun forgetSelfAdbKey()
}

class DefaultPrivilegedAccess(
    appId: String,
    private val phone: PhoneFacts,
    private val selfAdb: SelfAdbRoute,
    private val shizuku: ShizukuRoute,
    private val preferences: PrivilegedPreferences,
    private val rebinder: ListenerRebinder,
    private val redaction: OtpRedactionFlag,
    private val grayscale: GrayscaleReset,
    private val io: CoroutineDispatcher = Dispatchers.IO,
) : PrivilegedAccess {
    private val app: AppId? = AppId.parse(appId)
    private val statusFlow = MutableStateFlow(PrivilegedStatus.UNCHECKED)
    private val preferenceFlow = MutableStateFlow(preferences.route)
    private val busy = Mutex()

    /** Self-ADB looked usable on paper but the daemon was not there. In memory: a restart starts clean. */
    private val lostRoutes = ConcurrentHashMap<Route, RouteBlocker>()
    @Volatile private var lastSelfAdbReadiness: RouteReadiness? = null
package ly.com.tahaben.privileged_access_presentation

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import ly.com.tahaben.privileged_access_domain.Access
import ly.com.tahaben.privileged_access_domain.AccessResult
import ly.com.tahaben.privileged_access_domain.PairingCode
import ly.com.tahaben.privileged_access_domain.PairingResult
import ly.com.tahaben.privileged_access_domain.PrivilegedAccess
import ly.com.tahaben.privileged_access_domain.PrivilegedStatus
import ly.com.tahaben.privileged_access_domain.Route
import ly.com.tahaben.privileged_access_domain.RoutePreference
import ly.com.tahaben.privileged_access_domain.ShizukuPermissionResult
import javax.inject.Inject

/** What the connector's screens show. [status] carries the link and each access; the rest is the last thing the user did. */
data class PrivilegedAccessState(
    val status: PrivilegedStatus = PrivilegedStatus.UNCHECKED,
    val routePreference: RoutePreference = RoutePreference.DEFAULT,
    /** True while a command, a pairing or a permission prompt is in flight. */
    val working: Boolean = false,
    /** The last grant or revoke, until [PrivilegedAccessViewModel.dismissResult]. */
    val lastResult: AccessResult? = null,
    val lastPairing: PairingResult? = null,
    val lastShizukuPermission: ShizukuPermissionResult? = null,
)

/**
 * The calls the UI makes. Each one is something the user started: the connector runs no command on its own.
 * Re-check on return to the foreground with [onForeground]; the app also does it for the whole process.
 */
@HiltViewModel
class PrivilegedAccessViewModel @Inject constructor(
    private val access: PrivilegedAccess,
) : ViewModel() {
    private val activity = MutableStateFlow(Activity())

    val state: StateFlow<PrivilegedAccessState> = combine(access.status, access.routePreference, activity) { status, preference, activity ->
        PrivilegedAccessState(status, preference, activity.working, activity.result, activity.pairing, activity.shizuku)
    }.stateIn(viewModelScope, SharingStarted.Eagerly, PrivilegedAccessState())

    init {
        status()
    }

    /** Re-reads the link and each access. Runs nothing on the phone. */
    fun status() {
        viewModelScope.launch { access.refresh() }
    }

    fun onForeground() = status()

    /** [route] null: the stored preference, then the retained link; with neither, the result is `ChooseRoute`. */
    fun grantSensitiveNotifications(route: Route? = null) = command { access.grant(Access.SENSITIVE_NOTIFICATIONS, route) }

    fun grantSecureSettings(route: Route? = null) = command { access.grant(Access.SECURE_SETTINGS, route) }

    fun revokeSensitiveNotifications(route: Route? = null) = command { access.revoke(Access.SENSITIVE_NOTIFICATIONS, route) }

    fun revokeSecureSettings(route: Route? = null) = command { access.revoke(Access.SECURE_SETTINGS, route) }

    /** [code] and [pairingPort] are the raw text fields. A blank port means "find it"; the code is never kept. */
    fun pairSelfAdb(code: String, pairingPort: String = "") {
        val parsedCode = PairingCode.parse(code)
        val portText = pairingPort.trim()
        val port = portText.toIntOrNull()
        val portInvalid = portText.isNotEmpty() && (port == null || port !in 1..65535)
        if (parsedCode == null || portInvalid) return reject()
        working {
            activity.update { it.copy(pairing = null) }
            val result = access.pairSelfAdb(parsedCode, port)
            activity.update { it.copy(pairing = result) }
        }
    }

    fun requestShizukuPermission() = working {
package ly.com.tahaben.privileged_access_domain

import kotlinx.coroutines.CompletableDeferred

class FakePhone : PhoneFacts {
    override var sdk = 35
    var op = AppOpMode.NOT_ALLOWED
    var held = false
    var writeWorks: Boolean? = true
    override fun sensitiveNotificationsOp() = op
    override fun secureSettingsPermissionHeld() = held
    override fun secureSettingsWriteWorks() = writeWorks

    /** What a clean run of [command] does to the phone. */
    fun apply(command: PrivilegedCommand) {
        when (command) {
            PrivilegedCommand.GRANT_SENSITIVE_NOTIFICATIONS -> op = AppOpMode.ALLOWED
            PrivilegedCommand.REVOKE_SENSITIVE_NOTIFICATIONS -> op = AppOpMode.NOT_ALLOWED
            PrivilegedCommand.GRANT_SECURE_SETTINGS -> held = true
            PrivilegedCommand.REVOKE_SECURE_SETTINGS -> held = false
        }
    }
}

class FakePreferences(override var route: RoutePreference = RoutePreference.DEFAULT, override var linkDropPending: Boolean = false) : PrivilegedPreferences

/** Records order across fakes so a test can say "the grayscale reset ran before the revoke". */
class Journal { val events = mutableListOf<String>() }

abstract class FakeShell(override val route: Route, protected val phone: FakePhone, protected val journal: Journal) : PrivilegedShell {
    val ran = mutableListOf<ShellCommand>()
    var result: ShellResult? = null          // forced outcome; null means "run cleanly and change the phone"
    var gate: CompletableDeferred<Unit>? = null
    val entered = CompletableDeferred<Unit>()
    var applyEffect = true

    protected fun commandOf(shell: ShellCommand): PrivilegedCommand =
        PrivilegedCommand.entries.first { it.shellCommand(APP) == shell }

    override suspend fun run(command: ShellCommand): ShellResult {
        ran += command
        journal.events += "run ${command.args[0]} ${command.args[1]}"
        entered.complete(Unit)
        gate?.await()
        result?.let { return it }
        if (applyEffect) phone.apply(commandOf(command))
        return ShellResult.Ran(0, "")
    }

    companion object { val APP = AppId.parse("ly.com.tahaben.farhan_alpha")!! }
}

class FakeSelfAdb(phone: FakePhone, journal: Journal) : FakeShell(Route.SELF_ADB, phone, journal), SelfAdbRoute {
    var hasKey = false
    var wirelessOff = false
    var pairResult: PairingResult = PairingResult.Paired
    var pairCalls = 0
    var forgetCalls = 0
    var lastCode: PairingCode? = null
    var lastPairingPort: Int? = null

    override suspend fun readiness(): RouteReadiness = when {
        !hasKey -> RouteReadiness.Blocked(RouteBlocker.NOT_PAIRED)
        wirelessOff -> RouteReadiness.Blocked(RouteBlocker.WIRELESS_DEBUGGING_OFF)
        else -> RouteReadiness.Ready
    }

    override suspend fun pair(code: PairingCode, pairingPort: Int?): PairingResult {
        pairCalls++; lastCode = code; lastPairingPort = pairingPort
        if (pairResult == PairingResult.Paired) hasKey = true
        return pairResult
    }

    override fun forgetPairing() { forgetCalls++; hasKey = false }
}

class FakeShizuku(phone: FakePhone, journal: Journal) : FakeShell(Route.SHIZUKU, phone, journal), ShizukuRoute {
    var readiness: RouteReadiness = RouteReadiness.Blocked(RouteBlocker.SHIZUKU_NOT_INSTALLED)
    var permissionResult: ShizukuPermissionResult = ShizukuPermissionResult.Granted
    override suspend fun readiness() = readiness
    override suspend fun requestPermission(): ShizukuPermissionResult {
        if (permissionResult == ShizukuPermissionResult.Granted) readiness = RouteReadiness.Ready
        return permissionResult
    }
}

