package ly.com.tahaben.privileged_access_selfadb

/** One way of building the TLS side of a pairing connection, with the name the log and the report use for it. */
internal class PairingVariant(val label: String, val transport: PairingTransport)

internal object PairingVariants {
    /**
     * The first is what pairing uses. The others run only after the first one's TLS handshake failed, and only to say
     * whether the handshake would have worked another way: the platform's own TLS provider, and the certificate earlier
     * builds presented. All of them stop before the pairing code is used.
     */
    fun of(identity: AdbIdentity, nowMillis: Long = System.currentTimeMillis()): List<PairingVariant> {
        val key = identity.privateKey()
        val adbCertificate = identity.certificate()
        return listOf(
            PairingVariant("bundled Conscrypt, TLS 1.3, adb certificate", ConscryptPairingTransport(ConscryptTls(key, adbCertificate))),
            PairingVariant("platform TLS provider, TLS 1.3, adb certificate", ConscryptPairingTransport(ConscryptTls(key, adbCertificate, standalone = false))),
            PairingVariant(
                "bundled Conscrypt, TLS 1.3, previous certificate (CN=farhan, SHA-512)",
                ConscryptPairingTransport(ConscryptTls(key, LegacyCertificateShape.build(key, identity.publicKey(), nowMillis))),
            ),
        )
    }
}
