s=s[:a]+'''internal class AdbPairingClient(
    private val variants: List<PairingVariant>,
    private val spake2: (ByteArray) -> PairingSpake2 = ::NativeSpake2,
    private val log: StepLog = NoStepLog,
) {
    /**
     * Never throws: every failure comes back as [PairingOutcome.Broke] with the step and the exception class.
     *
     * The first variant is the real attempt. A later one runs only when the one before it failed its TLS handshake,
     * which is before the code is sent, so a code is never spent on a retry. If every handshake fails the first
     * variant's failure is the one reported; the log has them all.
     */
    fun pair(host: String, port: Int, code: String, adbPublicKey: ByteArray): PairingOutcome {
        var first: PairingOutcome.Broke? = null
        for ((index, variant) in variants.withIndex()) {
            log.note(OPERATION, null, "variant ${index + 1} of ${variants.size}: ${variant.label}; target $host:$port")
            val outcome = pairWith(variant.transport, host, port, code, adbPublicKey)
            val handshakeFailed = outcome is PairingOutcome.Broke && outcome.at.step == SelfAdbStep.TLS_HANDSHAKE
            if (handshakeFailed && index < variants.lastIndex) {
                if (first == null) first = outcome as PairingOutcome.Broke
                log.note(OPERATION, SelfAdbStep.TLS_HANDSHAKE, "variant ${index + 1} handshake failed; trying the next one (the code has not been sent)")
                continue
            }
            if (first != null) {
                log.note(OPERATION, null, "variant ${index + 1} (${variant.label}) ended: ${describe(outcome)}; variant 1 had failed at tls-handshake")
                if (handshakeFailed) return first
            }
            log.note(OPERATION, null, "result: ${describe(outcome)}")
            return outcome
        }
        return first ?: PairingOutcome.Rejected
    }

    private fun describe(outcome: PairingOutcome): String = when (outcome) {
        PairingOutcome.Paired -> "paired"
        PairingOutcome.Rejected -> "refused by the daemon"
        is PairingOutcome.Broke -> "broke at ${outcome.at.step.tag} (${outcome.at.exceptionClass})"
    }

    private fun pairWith(transport: PairingTransport, host: String, port: Int, code: String, adbPublicKey: ByteArray): PairingOutcome {
        val closer = mutableListOf<Closeable>()
        var crypto: PairingCrypto? = null
        return try {
            val plain = step(SelfAdbStep.CONNECT_SOCKET) { transport.connect(host, port) }
            closer += plain
            val tls = step(SelfAdbStep.TLS_HANDSHAKE) { transport.handshake(plain, host, port) }
            closer += tls
            log.note(OPERATION, SelfAdbStep.TLS_HANDSHAKE, tls.describe())
            val keying = step(SelfAdbStep.EXPORT_KEYING_MATERIAL) { tls.exportKeyingMaterial(EXPORTED_KEY_LABEL, EXPORTED_KEY_BYTES) }
            val input = DataInputStream(tls.input)
            val output = DataOutputStream(tls.output)

            val ready = step(SelfAdbStep.SPAKE2) {
                val made = PairingCrypto(spake2(code.toByteArray(Charsets.UTF_8) + keying)).also { crypto = it }
                writePacket(output, TYPE_SPAKE2, made.message)
                val theirs = readPacket(input, TYPE_SPAKE2)
                theirs != null && made.initCipher(theirs)
            }
            if (!ready) return PairingOutcome.Rejected

            val accepted = step(SelfAdbStep.PEER_INFO) { exchangePeerInfo(input, output, crypto!!, adbPublicKey) }
            if (accepted) PairingOutcome.Paired else PairingOutcome.Rejected
        } catch (stopped: StepException) {
            val failure = StepFailure.of(stopped.step, stopped.cause ?: stopped)
            log.failed(OPERATION, failure, stopped.cause)
            PairingOutcome.Broke(failure)
        } finally {
            try { crypto?.destroy() } catch (ignored: Throwable) { }
            closer.asReversed().forEach { try { it.close() } catch (ignored: Throwable) { } }
        }
    }

